def get_scenario(scenario_id: str) -> dict:
    normalized = scenario_id.upper().replace("SCENARIO-", "SC-")
    for scenario in SCENARIOS:
        if scenario["id"] == normalized:
            return scenario
    raise KeyError(scenario_id)
